draw:
var k = 8.99e9, e = 1.6e-19, me = 9.11e-31;
var R = p.R / 100, Q = p.Q * 1e-9;
var u0 = p.start;
var omega = Math.sqrt(e * k * Q / (me * R * R * R));

// integrate u'' = -u/(1+u^2)^{3/2} in units of 1/omega
var tau = (t * 1.4) % 60;
var u = u0, du = 0, dtau = 0.02;
var steps = Math.floor(tau / dtau);
if (steps > 3000) steps = 3000;
for (var i = 0; i < steps; i++) {
  var a = -u / Math.pow(1 + u * u, 1.5);
  du += a * dtau;
  u += du * dtau;
}

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var axisY = H * 0.26;
var left = 40, right = W - 20;
var zmax = 4.4;
function Z(uu) { return left + (uu + zmax) / (2 * zmax) * (right - left); }
var cx = Z(0);

// ring seen edge-on as an ellipse
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
var rr = (right - left) / (2 * zmax) * 0.55;
ctx.beginPath(); ctx.ellipse(cx, axisY, 7, 30, 0, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("ring, +" + p.Q.toFixed(0) + " nC", cx, axisY - 40);

// axis
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(left, axisY); ctx.lineTo(right, axisY); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "right";
ctx.fillText("axis (z)", right, axisY - 8);

// electron
var ex = Z(u);
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(ex, axisY, 5, 0, Math.PI * 2); ctx.fill();
ctx.textAlign = "center";
ctx.fillStyle = C.ink;
ctx.fillText("electron", ex, axisY + 20);

// V(z) curve below
var top = H * 0.52, bot = H * 0.94;
var Vc = k * Q / R;
function Y(v) { return bot - v / Vc * (bot - top) * 0.85; }
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 300; j++) {
  var uu = -zmax + 2 * zmax * j / 300;
  var v = k * Q / (R * Math.sqrt(1 + uu * uu));
  var px = Z(uu), py = Y(v);
  j === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
}
ctx.stroke();
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(left, bot); ctx.lineTo(right, bot); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.textAlign = "left";
ctx.fillText("V on the axis", left + 2, top + 2);
ctx.textAlign = "center";
ctx.fillText("peak V = kQ/R = " + Vc.toFixed(0) + " V", cx, top - 6);

// marker on the curve under the electron
var vnow = k * Q / (R * Math.sqrt(1 + u * u));
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(Z(u), Y(vnow), 4, 0, Math.PI * 2); ctx.fill();

var vcentre = Math.sqrt(2 * e * k * Q / (me * R) * (1 - 1 / Math.sqrt(1 + u0 * u0)));
var f = omega / (2 * Math.PI);
out.note = "speed at centre = " + (vcentre / 1e6).toFixed(2) + " x 10^6 m/s,   small-oscillation f = " + (f / 1e6).toFixed(1) + " MHz";
